function loadCardImage(img,name,complete){
 const data=CARD_DATA[name];
 const variants=data?[["ja",data.ja],["en",data.en]].filter(entry=>entry[1]):[];
 let at=0;
 function next(){
  const entry=variants[at++];
  if(!entry){img.onload=null;img.onerror=null;complete(false,null);return;}
  const [lang,url]=entry;
  img.onerror=next;
  img.onload=()=>{img.onload=null;img.onerror=null;complete(true,lang);};
  img.src=url;
 }
 next();
}

